func isNodeModuleAddon(name string) bool {
	switch name {
	case "console", "os", "querystring", "punycode", "timers", "timers/promises", "util", "util/types", "module", "url", "perf_hooks", "events", "domain", "diagnostics_channel", "trace_events", "assert", "assert/strict", "async_hooks", "constants", "vm", "child_process", "process", "string_decoder", "crypto", "net", "dns", "dns/promises", "worker_threads", "zlib", "cluster", "stream", "stream/iter", "stream/promises", "stream/consumers", "stream/web", "zlib/iter", "readline", "readline/promises", "tty", "repl", "wasi", "v8", "inspector", "inspector/promises", "http2", "quic", "sqlite", "test", "http", "https", "dgram", "_http_agent", "_http_incoming", "_http_common", "_http_outgoing", "_http_client", "_http_server":
		return true
	default:
		return false
	}
}
